var W = 900, H = 340;
var draw = SVG().addTo('#container').size('100%', '100%');
draw.viewbox(0, 0, W, H);

var CELL = 46, GAP = 0;
var X0 = 40, Y0 = 110;
var COL_LE = '#e8e8e8', COL_GT = '#9a9a9a', COL_UN = '#ffffff', COL_PIV = '#ffffff';
var SERIF = "Georgia, 'Times New Roman', serif";

/* ---------- state ---------- */
var demoMode = true;           // true = show 16-cell textbook figure; false = replay array
var demoArr = [];              // 16 cells: null = empty (textbook look)
var values = [];               // working array for replay (n cells)
var n = 16;
var pivotVal = null;
var curI = 3, curJ = 9;        // boundary positions (world indices)
var highlight = [];            // indices touched by current op
var captionMsg = '';
var frames = [], frameIdx = 0, playing = false, playTimer = null;

/* ---------- parse array input ---------- */
function parseArrayInput() {
  var src = document.getElementById('partitionEditorInput').value;
  var parts = src.split(',');
  var out = [];
  for (var k = 0; k < parts.length; k++) {
    var v = Number(parts[k].trim());
    if (parts[k].trim() === '' || !isFinite(v)) throw new Error('Array A: "' + parts[k].trim() + '" is not a number');
    out.push(v);
  }
  if (out.length < 2) throw new Error('Array A needs at least 2 elements');
  if (out.length > 16) throw new Error('Array A: max 16 elements');
  return out;
}

/* ---------- helpers ---------- */
function cellX(k) { return X0 + k * (CELL + GAP); }
function stripW() { return n * CELL; }

/* ---------- main draw (from state alone) ---------- */
var gMain = draw.group();
function redraw() {
  gMain.clear();
  var i, k;
  var totalW = stripW();
  X0 = (W - totalW) / 2;

  // cells
  for (k = 0; k < n; k++) {
    var col;
    if (k === n - 1) col = COL_PIV;
    else if (k <= curI) col = COL_LE;
    else if (k < curJ) col = COL_GT;
    else col = COL_UN;
    var r = gMain.rect(CELL, CELL).move(cellX(k), Y0)
      .fill(col).stroke({ color: '#000', width: 1 });
    if (highlight.indexOf(k) >= 0) r.stroke({ color: '#d62728', width: 3 });
  }

  // values inside cells
  for (k = 0; k < n; k++) {
    var txt;
    if (k === n - 1) {
      txt = (values.length && values[k] != null) ? 'x=' + values[k] : 'x';
    } else if (values.length && values[k] != null) {
      txt = String(values[k]);
    } else txt = '';
    if (txt) {
      var isPivot = (k === n - 1 && !(values.length && values[k] != null));
      gMain.text(txt)
        .font({ family: isPivot ? SERIF : 'sans-serif', size: isPivot ? 20 : 14, style: isPivot ? 'italic' : 'normal' })
        .attr({ 'text-anchor': 'middle' })
        .center(cellX(k) + CELL / 2, Y0 + CELL / 2);
    }
  }

  // boundary bars (drawn at index i, j, r as thick bars whose center is the slot boundary AFTER that index)
  function bar(afterIdx) {
    var x = cellX(afterIdx) + CELL; // right edge of cell afterIdx
    gMain.rect(7, CELL + 14).move(x - 3.5, Y0 - 7).fill('#000');
    return x;
  }
  var bxI = bar(curI), bxJ = (curJ !== curI) ? bar(curJ) : bxI, bxR = bar(n - 1);

  // top labels p, i, j, r
  function topLabel(str, x, yoff) {
    gMain.text(str).font({ family: SERIF, size: 24, style: 'italic' })
      .attr({ 'text-anchor': 'middle' })
      .center(x, Y0 - 22 + (yoff || 0));
  }
  topLabel('p', cellX(0) + CELL / 2);
  topLabel('i', bxI, -6);
  topLabel('j', (curJ !== curI) ? bxJ : bxI + 24, -6);
  topLabel('r', bxR, -6);

  // curly braces under regions
  function brace(x1, x2, label) {
    if (x2 - x1 < 20) return;
    var y = Y0 + CELL + 14, depth = 12, mid = (x1 + x2) / 2;
    var d = 'M ' + x1 + ' ' + y +
      ' C ' + (x1 + 6) + ' ' + (y + depth) + ' ' + (mid - 22) + ' ' + (y + depth) + ' ' + (mid - 6) + ' ' + (y + depth) +
      ' Q ' + mid + ' ' + (y + depth) + ' ' + mid + ' ' + (y + depth + 7) +
      ' Q ' + mid + ' ' + (y + depth) + ' ' + (mid + 6) + ' ' + (y + depth) +
      ' C ' + (mid + 22) + ' ' + (y + depth) + ' ' + (x2 - 6) + ' ' + (y + depth) + ' ' + x2 + ' ' + y;
    gMain.path(d).fill('none').stroke({ color: '#000', width: 1.4 });
    gMain.text(label).font({ family: SERIF, size: 19 })
      .attr({ 'text-anchor': 'middle' })
      .center(mid, y + depth + 24);
  }
  brace(cellX(0), cellX(curI) + CELL, '≤ x');
  if (curJ > curI + 1) brace(cellX(curI + 1), cellX(curJ - 1) + CELL, '> x');
  if (curJ <= n - 2) brace(cellX(curJ), cellX(n - 2) + CELL, 'unrestricted');

  // caption of current frame (small, under everything)
  if (captionMsg) {
    gMain.text(captionMsg).font({ family: 'sans-serif', size: 12 })
      .attr({ 'text-anchor': 'middle' })
      .center(W / 2, H - 16);
  }
}

/* ---------- demo (textbook) state ---------- */
function setupDemo() {
  demoMode = true;
  values = [];
  n = 16;
  curI = 3; curJ = 9;
  highlight = [];
  captionMsg = '';
  pivotVal = null;
  redraw();
}

/* ---------- test case toggle ---------- */
var TEST_LE = [2, 6, 8, 3, 9, 4];   // classic — exercises swap branch
var TEST_GT = [7, 9, 8, 6, 10, 4];  // all > pivot until end — no-swap branch
function toggle_testCase(on) {
