/* ---------- code editor: worker execution ---------- */
var apiOps = ['at', 'pivot', 'lessOrEqual', 'swap', 'note'];
var SAMPLES = {
  sample: "x = pivot()\ni = p - 1\nfor (j = p; j < r; j = j + 1) {\n  if (lessOrEqual(j)) {\n    i = i + 1\n    swap(i, j)\n  }\n}\nreturn i + 1",
  buggy: "x = pivot()\ni = p - 1\nfor (j = p; j < r; j = j + 1) {\n  if (lessOrEqual(j)) {\n    swap(i + 1, j)\n  }\n}\nreturn i + 1",
  blank: "// PARTITION(A, p, r): rearrange so A[p..q-1] <= x, A[q] = x, A[q+1..r] > x\n// Available: at(j), pivot(), lessOrEqual(j), swap(a,b), note(text)\nx = pivot()\n"
};
function loadTab(which) {
  document.getElementById('partitionEditorCode').value = SAMPLES[which];
  ['tabSample', 'tabBuggy', 'tabBlank'].forEach(function (id) {
    document.getElementById(id).classList.remove('active');
  });
  document.getElementById(which === 'sample' ? 'tabSample' : which === 'buggy' ? 'tabBuggy' : 'tabBlank').classList.add('active');
}

var WORKER_SRC = `
self.onmessage = function (e) {
  var code = e.data.code, arr = e.data.arr.slice();
  var p = 0, r = arr.length - 1;
  var frames = [], ops = 0;
  var MAX_OPS = 500, MAX_FRAMES = 400;
  function snap(kind, indices, message) {
    if (frames.length >= MAX_FRAMES) throw new Error('Frame cap reached (' + MAX_FRAMES + ')');
    frames.push({ kind: kind, state: arr.slice(), indices: indices.slice(), message: message });
  }
  function chk(idx, who) {
    if (typeof idx !== 'number' || idx !== Math.floor(idx) || idx < 0 || idx > r) {
      throw new Error(who + ': index ' + idx + ' out of range [0,' + r + ']');
    }
  }
  function bump() { if (++ops > MAX_OPS) throw new Error('Operation cap reached (possible infinite loop)'); }
  var api = {
    at: function (j) { bump(); chk(j, 'at'); snap('read', [j], 'read A[' + j + '] = ' + arr[j]); return arr[j]; },
    pivot: function () { bump(); snap('read', [r], 'pivot x = A[' + r + '] = ' + arr[r]); return arr[r]; },
    lessOrEqual: function (j) { bump(); chk(j, 'lessOrEqual'); var v = arr[j] <= arr[r]; snap('compare', [j, r], 'compare A[' + j + ']=' + arr[j] + ' with x=' + arr[r] + ' → ' + v); return v; },
    swap: function (a, b) { bump(); chk(a, 'swap'); chk(b, 'swap'); var t = arr[a]; arr[a] = arr[b]; arr[b] = t; snap('swap', [a, b], 'swap A[' + a + '] ↔ A[' + b + ']'); },
    note: function (t) { bump(); snap('note', [], String(t)); }
  };
  Object.freeze(api);
  try {
    var fn = new Function('A', 'p', 'r', 'at', 'pivot', 'lessOrEqual', 'swap', 'note', code);
    var ret = fn(arr, p, r, api.at, api.pivot, api.lessOrEqual, api.swap, api.note);
    self.postMessage({ ok: true, frames: frames, returned: ret, final: arr });
  } catch (err) {
    frames.push({ kind: 'error', state: arr.slice(), indices: [], message: 'Error: ' + err.message });
    self.postMessage({ ok: false, frames: frames, error: err.message, final: arr });
  }
};
`;

function setStatus(s) {
  var el = document.getElementById('runStatus');
  el.textContent = s;
  el.style.color = (s.indexOf('correct') === 0) ? '#1a7f1a' : (s.indexOf('not run') === 0 || s.indexOf('running') === 0) ? '#555' : '#c00000';
}

function trigger_partitionEditor() {
  var arr;
  var slot = document.getElementById('eq-err-partitionEditorInput');
  try {
    arr = parseArrayInput();
    slot.style.display = 'none';
  } catch (e) {
    slot.textContent = e.message; slot.style.display = '';
    return;
  }
  stopPlay();
  demoMode = false;
  setStatus('running…');
  document.getElementById('runBtn').disabled = true;

  var blob = new Blob([WORKER_SRC], { type: 'text/javascript' });
  var url = URL.createObjectURL(blob);
  var worker = new Worker(url);
  var done = false;
  var timer = setTimeout(function () {
    if (done) return; done = true;
    worker.terminate(); URL.revokeObjectURL(url);
    document.getElementById('runBtn').disabled = false;
    setStatus('error: timed out (1.5s)');
  }, 1500);

  worker.onmessage = function (e) {
    if (done) return; done = true;
    clearTimeout(timer);
    worker.terminate(); URL.revokeObjectURL(url);
    document.getElementById('runBtn').disabled = false;
    var d = e.data;
    frames = d.frames;
    frameIdx = 0;
    if (!frames.length) {
      frames = [{ kind: 'init', state: arr.slice(), indices: [], message: 'no operations recorded' }];
    }
    // success check
    if (d.ok) {
      var final = d.final, rr = final.length - 1, x = null;
      var q = d.returned;
      var okAll = false, badIdx = [];
      if (typeof q === 'number' && q === Math.floor(q) && q >= 0 && q <= rr) {
        x = null;
        okAll = true;
        // pivot should now sit at q with original A[r] value — check partition property
        var pv = final[q];
        for (var a = 0; a < q; a++) if (!(final[a] <= pv)) { okAll = false; badIdx.push(a); }
        for (var b = q + 1; b <= rr; b++) if (!(final[b] > pv)) { okAll = false; badIdx.push(b); }
      } else { badIdx = [0]; }
      if (okAll) {
        setStatus('correct ✓ pivot at index ' + q);
      } else {
        setStatus('wrong answer — invariant violated');
        if (badIdx.length && frames.length) frames[frames.length - 1].indices = badIdx;
      }
    } else {
      setStatus('error: ' + d.error);
    }
    showFrame(0);
    document.getElementById('frameCounter').textContent = '1 of ' + frames.length;
  };
  worker.onerror = function (e) {
    if (done) return; done = true;
    clearTimeout(timer); worker.terminate(); URL.revokeObjectURL(url);
    document.getElementById('runBtn').disabled = false;
    setStatus('error: ' + (e.message || 'worker failed'));
  };
  worker.postMessage({ code: document.getElementById('partitionEditorCode').value, arr: arr });
}

/* ---------- frame replay ---------- */
function showFrame(k) {
  if (!frames.length) return;
  frameIdx = Math.max(0, Math.min(frames.length - 1, k));
  var f = frames[frameIdx];
  demoMode = false;
  values = f.state.slice();
  n = values.length;
  // derive i, j from shading semantics: we can't know i directly — reconstruct:
  // i = last index of ≤-region relative to pivot = scan: everything in frames is stored in state;
  // we approximate bars: i = boundary between LE and GT region computed from values vs pivot
  var x = values[n - 1];
  // find j as the touched compare index if present, else first unrestricted
  // Simpler: recompute i as count of ≤-prefix is wrong mid-run. Instead store bars via message parse? No —
  // we recompute i/j from the frame's highlight + state:
  // convention: frame indices tell what op touched. For bars, we recompute i as the largest index
  // such that all values[0..i] <= x AND (i+1..j-1) > x. We search for the split consistent with state.
  var ii = -1;
  for (var a = 0; a < n - 1; a++) {
    if (values[a] <= x) ii = a; else break;
  }
  // verify i+1..? all > x to find j
  var jj = ii + 1;
  while (jj < n - 1 && values[jj] > x) jj++;
  // if op touched an index beyond jj (e.g. compare at j), extend j to cover it
  if (f.kind === 'compare' || f.kind === 'read') {
    for (var t = 0; t < f.indices.length; t++) {
      if (f.indices[t] < n - 1 && f.indices[t] >= jj) jj = f.indices[t];
    }
  }
  curI = ii; curJ = Math.max(jj, ii + 1);
  if (curJ > n - 1) curJ = n - 1;
  highlight = f.indices || [];
  captionMsg = f.message || '';
  document.getElementById('frameCaption').textContent = captionMsg;
  document.getElementById('frameCounter').textContent = (frameIdx + 1) + ' of ' + frames.length;
  redraw();
}
function frameFirst() { stopPlay(); showFrame(0); }
function framePrev() { stopPlay(); showFrame(frameIdx - 1); }
function frameNext() { stopPlay(); showFrame(frameIdx + 1); }
function stopPlay() {
  playing = false;
  if (playTimer) { clearInterval(playTimer); playTimer = null; }
  document.getElementById('playBtn').textContent = '▶';
}
function framePlay() {
  if (!frames.length) return;
  if (playing) { stopPlay(); return; }
  playing = true;
  document.getElementById('playBtn').textContent = '⏸';
  if (frameIdx >= frames.length - 1) showFrame(0);
  var speed = +document.getElementById('speedInput').value;
  playTimer = setInterval(function () {
    if (frameIdx >= frames.length - 1) { stopPlay(); return; }
    showFrame(frameIdx + 1);
  }, 1650 - speed);
}

